import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const owned = [];
  const primitiveResults = [];
  const timelines = [];

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const cardWidth = 2.25;
  const cardHeight = cardWidth * (320 / 512);

  const gradientMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: false
  });

  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.08, 0.92, uv().y)
  );

  const gradient = new Mesh(
    new PlaneGeometry(cardWidth, cardHeight),
    gradientMaterial
  );
  gradient.position.z = -0.012;
  root.add(gradient);
  owned.push(gradient.geometry, gradient.material);

  const grainMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.22
  });

  const grain = new Mesh(
    new PlaneGeometry(cardWidth, cardHeight),
    grainMaterial
  );
  grain.position.z = 0;
  root.add(grain);
  owned.push(grain.geometry, grain.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });

  const accentBar = new Mesh(
    new PlaneGeometry(0.055, cardHeight * 0.62),
    accentMaterial
  );
  accentBar.position.set(-cardWidth * 0.5 + 0.17, 0, 0.018);
  root.add(accentBar);
  owned.push(accentBar.geometry, accentBar.material);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of items) {
    const text = String(item.text ?? '');
    if (!text) continue;

    const label = ctx.fontAtlas.createText(text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left'
    });

    label.position.set(-cardWidth * 0.5 + 0.36, -0.04, 0.035);
    root.add(label);
  }

  const textureUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (textureUrl) {
    ctx.textureLoader.loadTexture(textureUrl).then((loadedTexture) => {
      if (!loadedTexture || root.userData.cleaned) return;

      loadedTexture.colorSpace = ctx.THREE.SRGBColorSpace;
      loadedTexture.wrapS = ctx.THREE.RepeatWrapping;
      loadedTexture.wrapT = ctx.THREE.RepeatWrapping;
      loadedTexture.repeat.set(1, 1);
      loadedTexture.offset.set(0, 0);

      grainMaterial.map = loadedTexture;
      grainMaterial.needsUpdate = true;
    });
  }

  grain.onBeforeRender = (_renderer, _scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const result of primitiveResults) {
      if (result?.cleanup) result.cleanup();
    }

    for (const resource of owned) {
      if (resource?.dispose) resource.dispose();
    }

    root.clear();
  };

  return root;
}
